#define _GNU_SOURCE
#include <unistd.h>
#include <fcntl.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <errno.h>

int main(int argc, char *argv[]) {
    if (argc < 3) {
        fprintf(stderr, "Usage: %s <file> <data>\n", argv[0]);
        return 1;
    }

    const char *file = argv[1];
    const char *data = argv[2];
    size_t data_len = strlen(data);

    // Open the target file read-only
    int fd_file = open(file, O_RDONLY);
    if (fd_file < 0) {
        perror("open target file");
        return 1;
    }

    // Create a pipe
    int pipe_fds[2];
    if (pipe(pipe_fds) < 0) {
        perror("pipe");
        return 1;
    }

    // Write data to the pipe
    ssize_t written = write(pipe_fds[1], data, data_len);
    if (written != (ssize_t)data_len) {
        perror("write to pipe");
        return 1;
    }

    // Use splice to write from pipe to the read-only file
    // The key is to use splice with SPLICE_F_MOVE flag
    loff_t offset = 0;
    ssize_t spliced = splice(pipe_fds[0], NULL, fd_file, &offset, data_len, SPLICE_F_MOVE);

    if (spliced < 0) {
        fprintf(stderr, "splice failed: %s\n", strerror(errno));
        close(fd_file);
        close(pipe_fds[0]);
        close(pipe_fds[1]);
        return 1;
    }

    printf("Successfully spliced %zu bytes\n", (size_t)spliced);

    close(fd_file);
    close(pipe_fds[0]);
    close(pipe_fds[1]);

    return 0;
}
